/**
 * A host-owned, synchronous atomic store. Callbacks may run on any calling thread.
 * The host initializes its state and must serialize CAS with every other writer.
 * Return false on revision conflict, or throw on I/O failure, without writing.
 * A true result means the complete state is durably committed before returning.
 */
public protocol NotebookStorageHost: AnyObject, Sendable {
    
    func descriptorJson() throws  -> String
    
    func loadJson() throws  -> String
    
    func compareAndSave(expectedRevision: UInt64, stateJson: String) throws  -> Bool
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceNotebookStorageHost {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceNotebookStorageHost = UniffiVTableCallbackInterfaceNotebookStorageHost(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceNotebookStorageHost.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface NotebookStorageHost: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceNotebookStorageHost.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface NotebookStorageHost: handle missing in uniffiClone")
            }
        },
        descriptorJson: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> String in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceNotebookStorageHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.descriptorJson(
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterString.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeNativeError_lower
            )
        },
        loadJson: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
